se up to 17 basic English letters, numbers, hyphens or underscores; do not add the wc- prefix. Check the saved slug because unsupported characters can be removed. Free can add definitions, but its Edit link is disabled.','routes'=>array('free'=>array('admin.php?page=wcj-tools&tab=custom_statuses'),'plus'=>array('admin.php?page=wcj-tools&tab=custom_statuses'),'elite'=>array('admin.php?page=wcj-tools&tab=custom_statuses')),'guide'=>'https://booster.io/docs/woocommerce-order-custom-statuses/#booster-v10-s20-order-custom-statuses-definition-editor','placement'=>'context','members'=>array('free'=>array('Status slug','Status name','Icon content','Icon color','Text color','Add custom status','Edit custom status (link disabled in Free)','Clear'),'plus'=>array('Status slug','Status name','Icon content','Icon color','Text color','Add custom status','Edit custom status','Clear'),'elite'=>array('Status slug','Status name','Icon content','Icon color','Text color','Add custom status','Edit custom status','Clear'))),array('group'=>'order_custom_statuses--definition-delete','module'=>'order_custom_statuses','label'=>'Remove status definitions deliberately','consequence'=>'These actions delete definitions/icon data, not a migration of existing orders. Do not treat recreating a label as restoring previous order effects.','context'=>'Check existing orders and integrations that use this status before deleting its definition. Deletion is not a safe way to move those orders to a different status. Keep a recoverable backup.','routes'=>array('free'=>array('admin.php?page=wcj-tools&tab=custom_statuses'),'plus'=>array('admin.php?page=wcj-tools&tab=custom_statuses'),'elite'=>array('admin.php?page=wcj-tools&tab=custom_statuses')),'guide'=>'https://booster.io/docs/woocommerce-order-custom-statuses/#booster-v10-s20-order-custom-statuses-definition-delete','placement'=>'context','members'=>array('free'=>array('Delete','Delete All Custom Statuses'),'plus'=>array('Delete','Delete All Custom Statuses'),'elite'=>array('Delete','Delete All Custom Statuses'))),array('group'=>'order_custom_statuses--order-actions','module'=>'order_custom_statuses','label'=>'Check status controls on existing orders','consequence'=>'Selecting an action changes order status and can invoke downstream behavior. A label or color alone does not establish payment, refund or fulfilment.','context'=>'Inspect the actual order list and preview used by your store. Buttons and bulk actions depend on their settings and edition. Do not click a transition merely to inspect its label.','routes'=>array('free'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_custom_statuses'),'plus'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_custom_statuses'),'elite'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_custom_statuses')),'guide'=>'https://booster.io/docs/woocommerce-order-custom-statuses/#booster-v10-s20-order-custom-statuses-order-actions','placement'=>'context','members'=>array('free'=>array('custom status action buttons (Plus and Elite only)','Processing/Complete buttons (Plus and Elite only)','bulk status entries','status colors (Plus and Elite only)'),'plus'=>array('custom status action buttons','Processing/Complete buttons','bulk status entries','status colors'),'elite'=>array('custom status action buttons','Processing/Complete buttons','bulk status entries','status colors'))),array('group'=>'order_numbers--renumerate-action','module'=>'order_numbers','label'=>'Renumber existing orders only deliberately','consequence'=>'The operation overwrites stored numbers and advances the counter. A change to formatting or tool sort options is not an Undo of the operation.','context'=>'Keep a recoverable database backup and an export of current identifiers before renumbering. Review the selected scope and next counter. Do not delete orders to reset numbering; label Undo cannot reverse renumbering.','routes'=>array('free'=>array('admin.php?page=wcj-tools&tab=renumerate_orders'),'plus'=>array('admin.php?page=wcj-tools&tab=renumerate_orders'),'elite'=>array('admin.php?page=wcj-tools&tab=renumerate_orders')),'guide'=>'https://booster.io/docs/woocommerce-custom-order-numbers/#booster-v10-s20-order-numbers-renumerate-action','placement'=>'context','members'=>array('free'=>array('Renumerate orders','Next number shown by the tool'),'plus'=>array('Renumerate orders','Next number shown by the tool'),'elite'=>array('Renumerate orders','Next number shown by the tool'))),array('group'=>'order_quantities--customer-quantities','module'=>'order_quantities','label'=>'Check customer quantity controls and messages','consequence'=>'A saved limit, the quantity input and purchase validation can behave differently. Check the products and checkout format you actually use before relying on a limit.','context'=>'Check simple products, the variations you sell, cart changes and checkout messages. Classic checkout and Blocks can differ. Restore the previous choices if a valid quantity is rejected; do not assume a hidden notice removes a limit.','routes'=>array('free'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_quantities'),'plus'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_quantities'),'elite'=>array('admin.php?page=wcj-plugins&wcj-cat=shipping_and_orders&section=order_quantities')),'guide'=>'https://booster.io/docs/woocommerce-order-min-max-quantities/#booster-v10-s20-order-quantities-customer-quantities','placement'=>'context','members'=>array('free'=>array('quantity input','variation quantity changes','loop Add to cart quantity','cart messages','checkout redirect'),'plus'=>array('quantity input','variation quantity changes','loop Add to cart quantity','cart messages','checkout redirect'),'elite'=>array('quantity input','variation quantity changes','loop Add to cart quantity','cart messages','checkout redirect'))),array('group'=>'orders--order-n